 assert r['status'] in {'RESOLVED','GENUINELY_PERIOD_WIDE','CONFLICTING','UNRESOLVED'}
 for c in r['candidates']:
  assert c['source_kind'] in {'PROPOSITION_EVIDENCE','OFFICIAL_RELEASE_DATE','RUNTIME_CONFIRMED_OCCURRENCE','SOURCE_PUBLISHED_AT','FOCUSED_WEB_SEARCH'}
# every admitted D gets fact and event rows, every pending only event row
for d in assigned:
 rs=[r for r in rows if r['delta_id']==d]
 if d in allcons:
  assert any(r['semantic_role']=='EVENT_OCCURRENCE' and r['event_id'] for r in rs)
  assert any(r['semantic_role']=='FACT_OCCURRENCE' and r['fact_id'] for r in rs)
 else:
