const r = await tools.exec_command({cmd:"python - <<'PY'
import json, pathlib, re, datetime, collections
root=pathlib.Path('.')
work=root/'attempts/o2-wave-015/output/work'
task=json.load(open(root/'attempts/o2-wave-015/input/task.json'))
assigned=task['assigned_delta_ids']; aset=set(assigned)
# draft structure/manual schema
allowed_types={'EARNINGS_RELEASE','GUIDANCE_UPDATE','ANALYST_ACTION','ANALYST_RESPONSE_EPISODE','INVESTOR_EVENT','PRODUCT_ANNOUNCEMENT','PRODUCT_MILESTONE','CAPACITY_OR_CAPEX','SUPPLY_DEMAND_UPDATE','MATERIAL_CONTRACT','FINANCING','CAPITAL_RETURN','M_AND_A','REGULATORY_ACTION','LITIGATION_MILESTONE','MANAGEMENT_CHANGE','MARKET_EPISODE','OTHER_CORPORATE_EVENT'}
prec={'TIMESTAMP','DAY','MONTH','QUARTER','YEAR','INTERVAL','UNKNOWN'}
states={'ACTUAL','GUIDANCE','FORECAST','PLAN','RUMOR','DENIAL','SCHEDULED','ONGOING','PLANNED','EXPECTED','RUMORED','DENIED','HYPOTHETICAL','UNKNOWN'}
drafts=[]
for p in sorted((work/'drafts').glob('T*.json')):
    x=json.load(open(p)); drafts.append(x)
    req={'event_id','ticker','title','event_type','occurred_at','occurrence_time_precision','canonical_summary','known_event_summary','is_important','include_in_reference_view','facts'}
    assert set(x)==req|{'price_analysis','related_event_ids','derived_from_event_ids','supersedes_event_id','status'},(p,set(x))
    assert x['event_type'] in allowed_types
    assert x['occurrence_time_precision'] in prec
    assert isinstance(x['facts'],list) and x['facts']
    assert x['price_analysis'] is None
    assert x['status'] in {'ACTIVE','SUPPRESSED','MERGED'}
    for f in x['facts']:
        assert set(f)=={'fact_id','proposition','assertion_state','fact_occurred_at','fact_occurrence_time_precision','subject_time','consumes_delta_ids'},(p,f)
        assert f['assertion_state'] in states
        assert f['fact_occurrence_time_precision']=='DAY'
        assert f['fact_occurred_at'] is not None
        assert all(d in aset for d in f['consumes_delta_ids'])
        assert f['consumes_delta_ids']
        if x['occurrence_time_precision']=='DAY':
            assert f['fact_occurred_at']=='SAME' or re.fullmatch(r'\d{4}-\d{2}-\d{2}',f['fact_occurred_at']), (p,f)
        else:
            assert re.fullmatch(r'\d{4}-\d{2}-\d{2}',f['fact_occurred_at']), (p,f)
cons=[]
for x in drafts:
    for f in x['facts']: cons += f['consumes_delta_ids']
print('drafts',len(drafts),'fact count',sum(len(x['facts']) for x in drafts),'consumed',len(cons),'unique',len(set(cons)),'dupes',[d for d,n in collections.Counter(cons).items() if n>1])
# wave index
wi=json.load(open(work/'wave_index.json')); assert set(wi)=={'entries'}
idx=[]
for e in wi['entries']:
    assert set(e)=={'candidate_key','assigned_delta_ids','draft_paths','unresolved_recommendation'}
    idx += e['assigned_delta_ids']
    for dp in e['draft_paths']:
        assert (root/dp).exists(),dp
print('wave assigned',len(idx),len(set(idx)),'exact',set(idx)==aset,'missing',sorted(aset-set(idx)),'extra',sorted(set(idx)-aset))
assert len(idx)==len(assigned) and set(idx)==aset and len(set(idx))==len(idx)
# pending inferred
print('pending wave',len(set(idx)-set(cons)),'resolved',len(set(cons)))
assert len(set(cons))==34
# ledgers
for fn in ['date_resolution_ledger.jsonl','reference_view_decision_ledger.jsonl']:
    lines=[json.loads(s) for s in open(work/fn) if s.strip()]
    print(fn,len(lines))
# date ledger checks
drows=[json.loads(s) for s in open(work/'date_resolution_ledger.jsonl') if s.strip()]
assert len(drows)==140
for row in drows:
    assert row['semantic_role'] in {'EVENT_OCCURRENCE','FACT_OCCURRENCE','SUBJECT_TIME'}
    assert row['status'] in {'RESOLVED','GENUINELY_PERIOD_WIDE','CONFLICTING','UNRESOLVED'}
    for c in row['candidates']:
        datetime.date.fromisoformat(c['candidate_date'])
        assert c['source_kind'] in {'PROPOSITION_EVIDENCE','OFFICIAL_RELEASE_DATE','RUNTIME_CONFIRMED_OCCURRENCE','SOURCE_PUBLISHED_AT','FOCUSED_WEB_SEARCH'}
    if row['selected_date'] is not None: datetime.date.fromisoformat(row['selected_date'])
    assert row['selected_precision'] in prec or row['selected_precision'] is None
# exact rows by delta-role
cnt=collections.Counter((r['delta_id'],r['semantic_role']) for r in drows)
assert all(n==1 for n in cnt.values()),[k for k,n in cnt.items() if n!=1]
assert set(d['delta_id'] for d in drows)==aset
print('ledger delta-role keys',len(cnt),'roles',collections.Counter(r['semantic_role'] for r in drows),'statuses',collections.Counter(r['status'] for r in drows))
# ref ledger
rrows=[json.loads(s) for s in open(work/'reference_view_decision_ledger.jsonl') if s.strip()]
assert len(rrows)==len(drafts)
print('reference',len(rrows),[r['event_id'] for r in rrows])
# output object shape
out={'status':'PENDING','stage':'LOCAL_RECONSTRUCTION','bundle_path':None,'base_library_version':0,'delta_coverage':{'total':72,'resolved':34,'pending':38},'validation':'NOT_RUN'}
print(json.dumps(out))
