allowed_types={'EARNINGS_RELEASE','GUIDANCE_UPDATE','ANALYST_ACTION','ANALYST_RESPONSE_EPISODE','INVESTOR_EVENT','PRODUCT_ANNOUNCEMENT','PRODUCT_MILESTONE','CAPACITY_OR_CAPEX','SUPPLY_DEMAND_UPDATE','MATERIAL_CONTRACT','FINANCING','CAPITAL_RETURN','M_AND_A','REGULATORY_ACTION','LITIGATION_MILESTONE','MANAGEMENT_CHANGE','MARKET_EPISODE','OTHER_CORPORATE_EVENT'}
prec={'TIMESTAMP','DAY','MONTH','QUARTER','YEAR','INTERVAL','UNKNOWN'}
states={'ACTUAL','GUIDANCE','FORECAST','PLAN','RUMOR','DENIAL','SCHEDULED','ONGOING','PLANNED','EXPECTED','RUMORED','DENIED','HYPOTHETICAL','UNKNOWN'}
drafts=[]; cons=[]
for p in sorted((work/'drafts').glob('T*.json')):
 x=json.load(open(p)); drafts.append(x)
 assert x['event_type'] in allowed_types and x['occurrence_time_precision'] in prec
 assert x['price_analysis'] is None and x['status']=='ACTIVE'
 for f in x['facts']:
  assert f['assertion_state'] in states and f['fact_occurrence_time_precision']=='DAY'
  assert f['consumes_delta_ids'] and all(d in aset for d in f['consumes_delta_ids'])
  if x['occurrence_time_precision']=='DAY': assert f['fact_occurred_at']=='SAME' or re.fullmatch(r'\d{4}-\d{2}-\d{2}',f['fact_occurred_at'])
  else: assert re.fullmatch(r'\d{4}-\d{2}-\d{2}',f['fact_occurred_at'])
  cons+=f['consumes_delta_ids']
assert len(cons)==len(set(cons))==34
wi=json.load(open(work/'wave_index.json')); ix=[d for e in wi['entries'] for d in e['assigned_delta_ids']]
assert len(ix)==len(set(ix))==72 and set(ix)==aset
rows=[json.loads(s) for s in open(work/'date_resolution_ledger.jsonl') if s.strip()]
assert len(rows)==140
for r in rows:
 assert r['semantic_role'] in {'EVENT_OCCURRENCE','FACT_OCCURRENCE','SUBJECT_TIME'}
 assert r['status'] in {'RESOLVED','GENUINELY_PERIOD_WIDE','CONFLICTING','UNRESOLVED'}
 for c in r['candidates']: datetime.date.fromisoformat(c['candidate_date'])
 if r['selected_date']: datetime.date.fromisoformat(r['selected_date'])
 assert r['selected_precision'] in prec or r['selected_precision'] is None
print('OK',len(drafts),len(cons),len(ix),len(rows),[d['event_id']+':'+d['occurred_at'] for d in drafts])
print('D680', [r for r in rows if r['delta_id']=='D680' and r['semantic_role']=='EVENT_OCCURRENCE'][0])
PY",workdir:"/data/workspaces/init-mu-1f3e9130ae304b01a7fdf2991a35e028-o2-mu-17d396ee65e3b48e",yield_time_ms:10000,max_output_tokens:5000});
