if importlib.util.find_spec('jsonschema'):
 from jsonschema import Draft202012Validator
 v=Draft202012Validator(schema)
 errs=[]
 for i,line in enumerate(open(p),1):
  d=json.loads(line)
  es=list(v.iter_errors(d))
  if es:
   errs.append((i,d,[e.message for e in es]))
 print('invalid rows',len(errs))
 c=collections.Counter(m for _,_,ms in errs for m in ms)
 print('messages',c)
 for i,d,ms in errs[:30]:
  print('\nLINE',i,ms); print(json.dumps(d,ensure_ascii=False))
# Check actual ISO calendar validity
bad=[]
for i,line in enumerate(open(p),1):
 d=json.loads(line)
 for k in ['selected_date']:
  if d.get(k):
   try: datetime.date.fromisoformat(d[k])
   except: bad.append((i,k,d[k]))
 for c in d.get('candidates',[]):
  try: datetime.date.fromisoformat(c['candidate_date'])
  except: bad.append((i,'candidate_date',c['candidate_date']))
print('calendar bad',len(bad),bad[:50])
