import json,re,collections,datetime,pathlib
root=pathlib.Path('.'); b=root/'attempts/o2-repair-001/output/revision_bundle'; p=root/'attempts/o2-global-reconciliation/output/revision_bundle'; errs=[]
events={}
for f in sorted((b/'events').glob('T*.json'),key=lambda x:int(x.stem[1:])):
 d=json.load(open(f)); events[d['event_id']]=d
 if f.read_bytes()!=(p/'events'/f.name).read_bytes(): errs.append(('event_changed',f.name))
facts={}; cons=[]
for eid,e in events.items():
 for f in e['facts']:
  facts[f['fact_id']]=(eid,f); cons.extend(f['consumes_delta_ids'])
res=[json.loads(x) for x in open(b/'residual_delta_resolutions.jsonl') if x.strip()]; resids=[d['delta_id'] for d in res]; assigned={f'D{i}' for i in range(1,997)}
if len(set(cons))!=len(cons): errs.append(('consume_duplicate',len(cons)-len(set(cons))))
if set(cons)&set(resids): errs.append(('coverage_overlap',len(set(cons)&set(resids))))
if set(cons)|set(resids)!=assigned: errs.append(('coverage_union',len((set(cons)|set(resids))^assigned)))
rows=[json.loads(x) for x in open(b/'date_resolution_ledger.jsonl') if x.strip()]
for i,d in enumerate(rows,1):
 if d['status']=='RESOLVED' and d['selected_date'] is None: errs.append(('resolved_null',i,d['delta_id'],d['semantic_role'],d['subject_time']))
 if d['selected_date'] is not None:
  try: datetime.date.fromisoformat(d['selected_date'])
  except: errs.append(('bad_date',i,d['selected_date']))
 if d['semantic_role']=='SUBJECT_TIME' and d['subject_time']=='2026-09-30' and d['selected_date']!='2026-09-30': errs.append(('subject_day_mismatch',i))
 if d['semantic_role']=='FACT_OCCURRENCE' and d['status']=='RESOLVED' and d['fact_id']:
  fid=d['fact_id']; eid,f=facts.get(fid,(None,None))
  expected=e['occurred_at'] if f and f['fact_occurred_at']=='SAME' else (f['fact_occurred_at'] if f else None)
  if expected and d['selected_date']!=expected: errs.append(('fact_date_mismatch',i,fid,d['selected_date'],expected))
if {d['delta_id'] for d in rows}!=assigned: errs.append(('ledger_id_set',len({d['delta_id'] for d in rows})))
for fid,(eid,f) in facts.items():
 expected=events[eid]['occurred_at'] if f['fact_occurred_at']=='SAME' else f['fact_occurred_at']
 if not any(d['fact_id']==fid and d['semantic_role']=='FACT_OCCURRENCE' and d['status']=='RESOLVED' and d['selected_date']==expected for d in rows): errs.append(('fact_ledger_missing',fid))
for d in rows:
 if d['semantic_role']=='EVENT_OCCURRENCE' and d['event_id'] and d['event_id'] in events and events[d['event_id']]['occurrence_time_precision']=='DAY' and d['status']=='RESOLVED' and d['selected_date']!=events[d['event_id']]['occurred_at']:
  errs.append(('event_date_mismatch',d['delta_id'],d['event_id'],d['selected_date']))
reviews=[json.loads(x) for x in open(b/'reference_review_decisions.jsonl') if x.strip()]; refs=[json.loads(x) for x in open(b/'reference_view_decision_ledger.jsonl') if x.strip()]
for r in reviews:
 e=events.get(r['event_id'])
 if not e: errs.append(('review_unknown',r['event_id'])); continue
 for k in ('is_important','include_in_reference_view'):
  if r[k]!=e[k]: errs.append(('review_event_flag',r['event_id'],k))
 if not r.get('note') or not r.get('reference_view_basis'): errs.append(('review_missing_decision',r['event_id']))
for ref in refs:
 r=next((x for x in reviews if x['event_id']==ref['event_id']),None)
 if not r: errs.append(('ref_unknown',ref['event_id'])); continue
 for a,c in [('is_important','is_important'),('include_in_reference_view','include_in_reference_view'),('reference_view_basis','reference_view_basis'),('note','note'),('review_reason','candidate_reason')]:
  if ref[a]!=r[c]: errs.append(('ref_mismatch',ref['event_id'],a))
if (b/'date_resolution_ledger.jsonl').read_bytes()!=(root/'attempts/o2-repair-001/output/work/date_resolution_ledger.jsonl').read_bytes(): errs.append(('date_copy',))
if (b/'reference_view_decision_ledger.jsonl').read_bytes()!=(root/'attempts/o2-repair-001/output/work/reference_view_decision_ledger.jsonl').read_bytes(): errs.append(('ref_copy',))
for d in rows:
 if d.get('selected_date') and d['selected_date']>'2026-09-09': errs.append(('after_asof',d['delta_id'],d['semantic_role'],d['selected_date']))
print('events',len(events),'facts',len(facts),'consumed',len(set(cons)),'pending',len(set(resids)),'rows',len(rows),'reviews',len(reviews),'refs',len(refs),'important',sum(d['is_important'] for d in reviews))
print('roles',collections.Counter(d['semantic_role'] for d in rows),'statuses',collections.Counter(d['status'] for d in rows))
print('errors',len(errs)); [print(x) for x in errs[:100]]
